package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
public final class GamesActivity extends LeoActivity {
 private PocketGames.Snake snake;private PocketGames.Sudoku sudoku;private PocketGames.Tiles tiles;private int game=-1,selected;private boolean paused=true,resumed;private Face face;private View playing;private final Handler clock=new Handler();
 private final Runnable tick=new Runnable(){public void run(){if(!resumed||paused||game!=0||snake==null)return;snake.tick();face.invalidate();if(snake.over){paused=true;int old=getPreferences(0).getInt("snake-best",0);if(snake.score>old)getPreferences(0).edit().putInt("snake-best",snake.score).apply();}else clock.postDelayed(this,Math.max(130,280-snake.score*5));}};
 protected void onCreate(Bundle b){super.onCreate(b);home();}
 private void home(){pause();game=-1;list(L.t("Jocuri Leo"),Arrays.asList(L.t("Snake · record ")+getPreferences(0).getInt("snake-best",0),L.t("Sudoku · progres salvat"),L.t("Puzzle 15 · progres salvat")),0,new Choice(){public void pick(int n){game=n;newGame(false);show();}},"",null);}
 private void newGame(boolean reset){long seed=System.currentTimeMillis();if(game==0)snake=new PocketGames.Snake(seed);else if(game==1){sudoku=new PocketGames.Sudoku(seed);if(!reset)sudoku.restore(getPreferences(0).getString("sudoku",""));}else{tiles=new PocketGames.Tiles(seed);if(!reset)tiles.restore(getPreferences(0).getString("tiles",""));}selected=0;paused=true;}
 private void show(){begin(new String[]{"Snake","Sudoku","Puzzle 15"}[game]);playing=root;face=new Face();root.addView(face,new LinearLayout.LayoutParams(-1,0,1));face.setFocusable(true);face.requestFocus();left=new Runnable(){public void run(){pause();options(L.t("Joc"),new String[]{L.t("Continuă"),L.t("Joc nou"),L.t("Alege alt joc"),L.t("Ajutor")},new Choice(){public void pick(int n){if(n==0){show();if(game==0)resumeSnake();}else if(n==1)options(L.t("Începi un joc nou?"),new String[]{L.t("Păstrează progresul"),L.t("Joc nou")},new Choice(){public void pick(int yes){if(yes==1){newGame(true);persist();show();}}});else if(n==2){persist();home();}else notice(game==0?L.t("D-pad direcție · OK pornește/pauză"):game==1?L.t("D-pad selectează · 1–9 scrie · 0 șterge. Cifrele în conflict sunt refuzate."):L.t("D-pad mută spațiul gol. Așază piesele 1–15."));}});}};back=new Runnable(){public void run(){persist();home();}};footer(L.t("Opțiuni"),game==0?L.t("OK pauză / start"):game==1?L.t("1–9 · 0 șterge"):L.t("D-pad mută"),L.t("Jocuri"));}
 private void pause(){paused=true;clock.removeCallbacks(tick);if(face!=null)face.invalidate();}
 private void resumeSnake(){if(snake.over){notice(L.t("Joc încheiat · Opțiuni → Joc nou"));return;}paused=false;clock.removeCallbacks(tick);if(resumed)clock.postDelayed(tick,200);face.invalidate();}
 private void persist(){if(game==1&&sudoku!=null)getPreferences(0).edit().putString("sudoku",sudoku.save()).apply();if(game==2&&tiles!=null)getPreferences(0).edit().putString("tiles",tiles.save()).apply();}
 protected void onResume(){super.onResume();resumed=true;}
 protected void onPause(){resumed=false;pause();persist();super.onPause();}
 protected void onDestroy(){clock.removeCallbacksAndMessages(null);super.onDestroy();}
 public boolean onKeyDown(int key,KeyEvent e){if(root==playing&&game>=0){int d=key==19?0:key==22?1:key==20?2:key==21?3:-1;if(d>=0){if(game==0)snake.turn(d);else if(game==1){int row=selected/9,col=selected%9;row=Math.floorMod(row+(d==0?-1:d==2?1:0),9);col=Math.floorMod(col+(d==3?-1:d==1?1:0),9);selected=row*9+col;}else if(e.getRepeatCount()==0&&!tiles.done())tiles.move(d);face.invalidate();return true;}if(game==0&&(key==23||key==66)){if(e.getRepeatCount()==0){if(paused)resumeSnake();else pause();}return true;}if(game==1&&key>=7&&key<=16){if(e.getRepeatCount()==0&&!sudoku.place(selected,key-7))notice(L.t("Celulă fixă sau cifră în conflict"));face.invalidate();return true;}}return super.onKeyDown(key,e);}
 private final class Face extends View {
  final Paint p=new Paint(3);Face(){super(GamesActivity.this);}void label(Canvas c,String s,float x,float y,int size,int color){p.setColor(color);p.setTextSize(size);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextAlign(Paint.Align.CENTER);c.drawText(s,x,y,p);}
  protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/224f);c.drawColor(palette.background);
   if(game==0){label(c,L.t("Scor ")+snake.score+" · "+(snake.over?(snake.won?L.t("Ai câștigat"):L.t("Joc încheiat")):paused?L.t("OK pentru start"):"Snake"),120,18,13,Color.WHITE);p.setColor(palette.card);c.drawRect(24,25,216,221,p);for(int at:snake.body){p.setColor(at==snake.body.peekFirst()?Color.WHITE:palette.accent);float x=24+(at%12)*16,y=25+(at/12)*14;c.drawRoundRect(x+1,y+1,x+15,y+13,3,3,p);}if(snake.food>=0){p.setColor(0xffffba65);c.drawCircle(32+snake.food%12*16,32+snake.food/12*14,4,p);}}
   else if(game==1){label(c,sudoku.done()?L.t("Felicitări!"):L.t("1–9 completează · 0 șterge"),120,16,12,Color.WHITE);for(int i=0;i<81;i++){float x=12+i%9*24,y=27+i/9*21;p.setColor(i==selected?palette.selection:palette.card);c.drawRect(x,y,x+23,y+20,p);if(sudoku.cells[i]!=0)label(c,""+sudoku.cells[i],x+12,y+16,15,i==selected?palette.ink:sudoku.given[i]!=0?Color.WHITE:palette.accent);}p.setColor(palette.accent);p.setStrokeWidth(2);for(int i=0;i<=3;i++){c.drawLine(12+i*72,27,12+i*72,216,p);c.drawLine(12,27+i*63,228,27+i*63,p);}}
   else{label(c,tiles.done()?L.t("Felicitări!"):L.t("Mutări · ")+tiles.moves,120,20,14,Color.WHITE);for(int i=0;i<16;i++){float x=24+i%4*48,y=28+i/4*47;p.setColor(tiles.cells[i]==0?palette.background:palette.card);c.drawRoundRect(x+2,y+2,x+46,y+45,6,6,p);if(tiles.cells[i]!=0)label(c,""+tiles.cells[i],x+24,y+31,23,tiles.cells[i]==i+1?palette.accent:Color.WHITE);}}c.restore();
  }
 }
}
